-- Aligns the active high-one cohort to the latest teacher-confirmed lesson boundary.
begin;
create temporary table four_week_plan_template(cohort text,day_index integer,mode text,title text,skill_ids text[],knowledge_summaries text[],estimated_minutes smallint) on commit drop;
delete from public.chem_learning_plans p using public.chem_students_v2 s where p.student_id=s.id and p.plan_date between date '2026-08-13' and date '2026-09-09' and s.metadata->>'curriculumCohort' in ('junior_foundation','high1_current','high1_completed','high2_xb1_complete','high3_quality_0827');
select s.id,date '2026-08-13'+t.day_index,t.mode,t.title,t.skill_ids,t.knowledge_summaries,t.estimated_minutes,'mixed',true
from public.chem_students_v2 s join four_week_plan_template t on t.cohort=s.metadata->>'curriculumCohort';
commit;
