insert into public.chem_skills(id,title,module_id,grade_band,max_level,exam_importance,exam_depth,prerequisites,level_criteria,active) values('H1_ELECTROLYTE_INTRO','电解质与非电解质基础','H1-F01A','高一',4,5,3,array[]::text[],'[{"level":1,"studentFacingGoal":"电解质与非电解质基础 L1","requiredAbility":"能识别并解释基础概念"},{"level":2,"studentFacingGoal":"电解质与非电解质基础 L2","requiredAbility":"能识别并解释基础概念"},{"level":3,"studentFacingGoal":"电解质与非电解质基础 L3","requiredAbility":"能在变化情境中迁移"},{"level":4,"studentFacingGoal":"电解质与非电解质基础 L4","requiredAbility":"能在变化情境中迁移"}]'::jsonb,true) on conflict(id) do update set title=excluded.title,module_id=excluded.module_id,grade_band=excluded.grade_band,max_level=excluded.max_level,exam_importance=excluded.exam_importance,exam_depth=excluded.exam_depth,level_criteria=excluded.level_criteria,active=true,updated_at=now();
insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H1_ELECTROLYTE_INTRO','H1_ELECTROLYTE_INTRO','电解质与非电解质基础','先限定研究对象是化合物，再判断它在水溶液中或熔融状态能否自身产生自由移动的离子。','本模块只覆盖第一讲已学的电解质概念和导电微观原因，不提前书写离子方程式或处理离子共存。','["确认研究对象是否为化合物","判断是否自身电离产生离子","区分物质本身与其水溶液","用微观粒子解释导电"]'::jsonb,'["把能导电的金属单质判成电解质","把水溶液导电直接等同于溶质是电解质"]'::jsonb,'熔融NaCl含可自由移动的Na⁺和Cl⁻，NaCl属于电解质。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_ELECTROLYTE_INTRO_01','M4W_H1_ELECTROLYTE_INTRO_1','H1_ELECTROLYTE_INTRO',2,'高一','下列物质属于电解质的是','["铜","蔗糖","NaCl","酒精"]'::jsonb,2,'NaCl是化合物，在熔融状态或水溶液中能产生自由移动的离子。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_ELECTROLYTE_INTRO_02','M4W_H1_ELECTROLYTE_INTRO_2','H1_ELECTROLYTE_INTRO',2,'高一','铜能导电但不属于电解质，主要因为铜是','["单质","化合物","酸","盐"]'::jsonb,0,'电解质和非电解质的研究对象都是化合物，铜是单质。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_ELECTROLYTE_INTRO_03','M4W_H1_ELECTROLYTE_INTRO_3','H1_ELECTROLYTE_INTRO',2,'高一','NaCl溶液能导电的直接原因是','["存在自由移动的Na⁺和Cl⁻","NaCl分子定向移动","水分子带正电","溶液中没有粒子"]'::jsonb,0,'自由移动的离子在电场中定向移动形成电流。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_ELECTROLYTE_INTRO_04','M4W_H1_ELECTROLYTE_INTRO_4','H1_ELECTROLYTE_INTRO',2,'高一','下列物质属于非电解质的是','["HCl","NaOH","蔗糖","NaCl"]'::jsonb,2,'蔗糖是化合物，溶于水以分子存在，不能自身电离。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_ELECTROLYTE_INTRO_05','M4W_H1_ELECTROLYTE_INTRO_5','H1_ELECTROLYTE_INTRO',2,'高一','判断某化合物是否为电解质时，不能只依据','["其水溶液是否导电","能否自身产生离子","熔融状态是否产生离子","是否属于化合物"]'::jsonb,0,'有些物质与水反应生成电解质使溶液导电，不能只看水溶液导电。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_ELECTROLYTE_INTRO_06','M4W_H1_ELECTROLYTE_INTRO_6','H1_ELECTROLYTE_INTRO',2,'高一','关于电解质的说法正确的是','["电解质一定是化合物","能导电的物质都是电解质","电解质必须在固态导电","金属都是电解质"]'::jsonb,0,'电解质的研究对象必须是化合物。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_ELECTROLYTE_INTRO_07','M4W_H1_ELECTROLYTE_INTRO_7','H1_ELECTROLYTE_INTRO',3,'高一','关于“电解质与非电解质基础”的核心规律，下列说法正确的是','["先限定研究对象是化合物，再判断它在水溶液中或熔融状态能否自身产生自由移动的离子。","把能导电的金属单质判成电解质","把水溶液导电直接等同于溶质是电解质","题目条件不会影响判断"]'::jsonb,0,'该模块的核心规律是：先限定研究对象是化合物，再判断它在水溶液中或熔融状态能否自身产生自由移动的离子。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_ELECTROLYTE_INTRO_08','M4W_H1_ELECTROLYTE_INTRO_8','H1_ELECTROLYTE_INTRO',3,'高一','处理“电解质与非电解质基础”问题时，最可靠的第一步是','["确认研究对象是否为化合物","把能导电的金属单质判成电解质","先猜答案再补理由","忽略题设条件直接套公式"]'::jsonb,0,'第一步应先确认研究对象是否为化合物，之后才能稳定迁移。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_skills(id,title,module_id,grade_band,max_level,exam_importance,exam_depth,prerequisites,level_criteria,active) values('H1_MOLE_INTRO','物质的量、阿伏加德罗常数与摩尔质量','H1-F05A','高一',5,5,4,array[]::text[],'[{"level":1,"studentFacingGoal":"物质的量、阿伏加德罗常数与摩尔质量 L1","requiredAbility":"能识别并解释基础概念"},{"level":2,"studentFacingGoal":"物质的量、阿伏加德罗常数与摩尔质量 L2","requiredAbility":"能识别并解释基础概念"},{"level":3,"studentFacingGoal":"物质的量、阿伏加德罗常数与摩尔质量 L3","requiredAbility":"能在变化情境中迁移"},{"level":4,"studentFacingGoal":"物质的量、阿伏加德罗常数与摩尔质量 L4","requiredAbility":"能在变化情境中迁移"},{"level":5,"studentFacingGoal":"物质的量、阿伏加德罗常数与摩尔质量 L5","requiredAbility":"能在变化情境中迁移"}]'::jsonb,true) on conflict(id) do update set title=excluded.title,module_id=excluded.module_id,grade_band=excluded.grade_band,max_level=excluded.max_level,exam_importance=excluded.exam_importance,exam_depth=excluded.exam_depth,level_criteria=excluded.level_criteria,active=true,updated_at=now();
insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H1_MOLE_INTRO','H1_MOLE_INTRO','物质的量、阿伏加德罗常数与摩尔质量','先看清微粒对象，再用n连接粒子数N和质量m。','本模块只覆盖已经讲过的物质的量、阿伏加德罗常数、摩尔质量及一步换算；不提前使用气体摩尔体积、溶液浓度或反应计量。','["确认微粒对象","选择N=nNₐ或n=m/M","统一单位并计算","回看数量级是否合理"]'::jsonb,'["把1 mol误认为1个粒子","把摩尔质量写成没有单位的相对分子质量"]'::jsonb,'18 g H₂O的物质的量为1 mol，含约Nₐ个水分子。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
