insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_MOLE_INTRO_02','M4W_H1_MOLE_INTRO_2','H1_MOLE_INTRO',2,'高一','1 mol任何微粒集合所含微粒数约为','["6.02×10²³","22.4","1.00×10⁻³","18"]'::jsonb,0,'1 mol指定微粒所含微粒数约为阿伏加德罗常数。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
